// Package versions keeps the scaffold's stack versions tied to the repository's single sources of
// truth and reports upstream updates for the npm-pinned front-end assets. | Package versions 让脚手架
// 的技术栈版本与仓库的唯一真源保持一致，并报告 npm 前端资产的上游更新。
//
// The two sources are go.mod (the go directive and the direct module requirements) and
// web/assets.lock.json (the pinned asset versions). Nothing in this package duplicates them: the
// scaffold's GoVersion and HtmxVersion are *generated* from these files by `yd versions sync`, and
// `yd versions check` fails when the generated file drifts. That is what keeps `yd new` from
// shipping stale versions after a dependency upgrade. | 两个真源是 go.mod（go 指令与直接依赖）
// 和 web/assets.lock.json（锁定的资产版本）。本包不复制它们：脚手架的 GoVersion 与 HtmxVersion
// 由 `yd versions sync` 从这两个文件**生成**，`yd versions check` 在生成文件漂移时失败。
// 这正是依赖升级后 `yd new` 不会继续产出旧版本的原因。
package versions

import (
	"errors"
	"go/format"
	"io/fs"
	"path/filepath"
	"sort"
	"strconv"
	"strings"

	"github.com/spf13/afero"

	"github.com/shibingli/yd/tooling/assets"
	"github.com/shibingli/ydx/errs"
)

const (
	// GoModPath is the module file whose go directive the scaffold follows. | GoModPath 是脚手架跟随其 go 指令的模块文件。
	GoModPath = "go.mod"
	// GeneratedPath is the generated file that the scaffold package consumes. | GeneratedPath 是 scaffold 包消费的生成文件。
	GeneratedPath = "tooling/scaffold/version_generated.go"
	// generatedMarker is the mandatory marker of generated files. | generatedMarker 是生成文件的强制标记。
	generatedMarker = "// Code generated by yd versions sync; DO NOT EDIT.\n"
)

var (
	// ErrGoMod is returned when go.mod cannot be read. | ErrGoMod 表示 go.mod 无法读取。
	ErrGoMod = errs.New("read go.mod failed | 读取 go.mod 失败")
	// ErrGoModInvalid is returned when go.mod lacks the module or go directive. | ErrGoModInvalid 表示 go.mod 缺少 module 或 go 指令。
	ErrGoModInvalid = errs.New("go.mod is missing the module or go directive | go.mod 缺少 module 或 go 指令")
	// ErrNoHtmxAsset is returned when the asset manifest has no htmx entry. | ErrNoHtmxAsset 表示资产清单缺少 htmx 条目。
	ErrNoHtmxAsset = errs.New("asset manifest has no htmx entry | 资产清单缺少 htmx 条目")
	// ErrGeneratedDrift is returned when the generated scaffold versions differ from the sources. | ErrGeneratedDrift 表示生成的脚手架版本与真源不一致。
	ErrGeneratedDrift = errs.New("scaffold versions differ from the source of truth | 脚手架版本与版本真源不一致")
)

// Module is one module requirement of go.mod. | Module 是 go.mod 的一条模块依赖。
type Module struct {
	// Path is the module path. | Path 是模块路径。
	Path string
	// Version is the required version. | Version 是要求的版本。
	Version string
}

// Inventory is the version snapshot derived from go.mod and the asset lock. | Inventory 是从 go.mod 与资产锁文件推导出的版本快照。
type Inventory struct {
	// ModulePath is the module path declared by go.mod. | ModulePath 是 go.mod 声明的模块路径。
	ModulePath string
	// GoDirective is the go directive, for example "1.27.3". | GoDirective 是 go 指令，例如 "1.27.3"。
	GoDirective string
	// HtmxVersion is the version of the asset named "htmx". | HtmxVersion 是名为 htmx 的资产版本。
	HtmxVersion string
	// YdxVersions maps each ydx module required by the framework to its own tag; empty when none.
	// | YdxVersions 把框架依赖的每个 ydx 模块映射到它自己的标签版本；没有 ydx 依赖时为空。
	YdxVersions map[string]string
	// YdxModules are the ydx module paths required by the framework, sorted by path. | YdxModules 是框架要求的 ydx 模块路径，按路径排序。
	YdxModules []string
	// WafModuleVersion is the ydx WAF module version pinned by the nested WAF dependency module.
	// | WafModuleVersion 是嵌套 WAF 依赖模块锁定的 ydx WAF 模块版本。
	WafModuleVersion string
	// CRSRulesetVersion is the OWASP CRS version pinned by the nested WAF dependency module. |
	// CRSRulesetVersion 是嵌套 WAF 依赖模块锁定的 OWASP CRS 版本。
	CRSRulesetVersion string
	// Modules are the direct requirements, sorted by path. | Modules 是直接依赖，按路径排序。
	Modules []Module
	// Assets is the locked asset list, sorted by name. | Assets 是锁定的资产列表，按名字排序。
	Assets []assets.Asset
}

// validGoDirective reports whether s is a two- or three-part numeric Go version. | validGoDirective
// 报告 s 是否为两段或三段数字组成的 Go 版本。
func validGoDirective(s string) bool {
	parts := strings.Split(s, ".")
	if len(parts) < 2 || len(parts) > 3 {
		return false
	}
	for _, p := range parts {
		if p == "" {
			return false
		}
		for _, r := range p {
			if r < '0' || r > '9' {
				return false
			}
		}
	}
	return true
}

// validVersionToken reports whether s looks like a semantic version (an optional v prefix, a
// numeric core and optional prerelease/build suffixes). | validVersionToken 报告 s 是否形如语义化
// 版本（可选 v 前缀、数字主体与可选的预发布/构建后缀）。
func validVersionToken(s string) bool {
	s = strings.TrimPrefix(strings.TrimSpace(s), "v")
	if s == "" {
		return false
	}
	core, _, _ := strings.Cut(s, "-")
	core, _, _ = strings.Cut(core, "+")
	parts := strings.Split(core, ".")
	if len(parts) < 2 || len(parts) > 3 {
		return false
	}
	for _, p := range parts {
		if p == "" {
			return false
		}
		for _, r := range p {
			if r < '0' || r > '9' {
				return false
			}
		}
	}
	for _, r := range s {
		switch {
		case r >= '0' && r <= '9', r >= 'a' && r <= 'z', r >= 'A' && r <= 'Z', r == '.', r == '-', r == '+':
		default:
			return false
		}
	}
	return true
}

// HasScaffold reports whether dir contains the scaffold sources. | HasScaffold 报告 dir 是否包含脚手架源码。
//
// The framework repository owns tooling/scaffold and therefore owns the generated version file; a
// project produced by `yd new` does not. check and sync must skip the generated-file half there
// instead of creating a stray tooling tree inside the user's project. | 框架仓库拥有 tooling/scaffold，
// 因而拥有生成的版本文件；`yd new` 生成的项目没有。check 与 sync 必须在后者跳过生成文件这一半，
// 而不是在用户项目里创建多余的 tooling 目录树。
func HasScaffold(fsys afero.Fs, dir string) bool {
	info, err := fsys.Stat(filepath.Join(dir, filepath.FromSlash("tooling/scaffold")))
	return err == nil && info.IsDir()
}

// WafDepsDir is the nested module holding the optional WAF dependencies. Keeping them in a
// separate module stops the WAF engine's third-party requirements (libinjection-go and wazero)
// and the CRS rule bundle from entering the framework's root go.mod. | WafDepsDir 是承载可选
// WAF 依赖的嵌套模块。把它们放在独立模块中，可阻止 WAF 引擎的第三方依赖（libinjection-go 与
// wazero）以及 CRS 规则包进入框架根 go.mod。
const WafDepsDir = "tooling/versions/waf"

// wafDepsGoModPath is the nested module file relative to the project directory. | wafDepsGoModPath
// 是嵌套模块文件相对项目目录的路径。
const wafDepsGoModPath = WafDepsDir + "/go.mod"

// wafModulePath is the ydx WAF module path pinned by the nested module. | wafModulePath 是嵌套模块
// 锁定的 ydx WAF 模块路径。
const wafModulePath = "github.com/shibingli/ydx/waf"

// wafCRSModulePath is the OWASP CRS module path pinned by the nested module. | wafCRSModulePath 是
// 嵌套模块锁定的 OWASP CRS 模块路径。
const wafCRSModulePath = "github.com/corazawaf/coraza-coreruleset/crs/v4"

// HasWafDeps reports whether dir contains the nested WAF dependency module. | HasWafDeps 报告 dir
// 是否包含嵌套 WAF 依赖模块。
func HasWafDeps(fsys afero.Fs, dir string) bool {
	info, err := fsys.Stat(filepath.Join(dir, filepath.FromSlash(wafDepsGoModPath)))
	return err == nil && !info.IsDir()
}

// loadWAFVersions reads the two pins from the nested WAF dependency module. | loadWAFVersions 从
// 嵌套 WAF 依赖模块读取两个版本。
func loadWAFVersions(fsys afero.Fs, dir string) (waf, crs string, err error) {
	path := filepath.Join(dir, filepath.FromSlash(wafDepsGoModPath))
	data, err := afero.ReadFile(fsys, path)
	if err != nil {
		return "", "", errs.WrapDetail(err, ErrGoMod, "path %[1]q | 路径 %[1]q", path)
	}
	_, _, _, modules, err := parseGoMod(string(data))
	if err != nil {
		return "", "", errs.WrapDetail(err, ErrGoModInvalid, "path %[1]q | 路径 %[1]q", path)
	}
	for _, m := range modules {
		switch m.Path {
		case wafModulePath:
			waf = m.Version
		case wafCRSModulePath:
			crs = m.Version
		}
	}
	if waf == "" {
		return "", "", errs.Detail(ErrGoModInvalid, "path %[1]q: missing %[2]s | 路径 %[1]q：缺少 %[2]s", path, wafModulePath)
	}
	if crs == "" {
		return "", "", errs.Detail(ErrGoModInvalid, "path %[1]q: missing %[2]s | 路径 %[1]q：缺少 %[2]s", path, wafCRSModulePath)
	}
	return waf, crs, nil
}

// Load reads go.mod and the asset lock from fsys, whose root is the project directory. | Load 从 fsys 读取 go.mod 与资产锁文件，fsys 的根是项目目录。
//
// The asset path follows assets.DefaultManifestPath, so the same call works for the framework
// repository and for a generated project. | 资产路径沿用 assets.DefaultManifestPath，因此同一调用
// 既适用于框架仓库，也适用于生成的项目。
func Load(fsys afero.Fs, dir string) (*Inventory, error) {
	if fsys == nil {
		return nil, errs.Detail(ErrGoMod, "nil file system | 文件系统为 nil")
	}
	modPath := filepath.Join(dir, GoModPath)
	data, err := afero.ReadFile(fsys, modPath)
	if err != nil {
		return nil, errs.WrapDetail(err, ErrGoMod, "path %[1]q | 路径 %[1]q", modPath)
	}
	modulePath, goDirective, modules, allModules, err := parseGoMod(string(data))
	if err != nil {
		return nil, errs.WrapDetail(err, ErrGoMod, "path %[1]q | 路径 %[1]q", modPath)
	}
	if !validGoDirective(goDirective) {
		return nil, errs.Detail(ErrGoModInvalid, "go directive %[1]q is not a version | go 指令 %[1]q 不是合法版本", goDirective)
	}
	manifestPath := filepath.Join(dir, filepath.FromSlash(assets.DefaultManifestPath))
	m, err := assets.LoadManifest(fsys, manifestPath)
	if err != nil {
		return nil, err
	}
	htmx, ok := m.Find("htmx")
	if !ok || htmx.Version == "" {
		return nil, errs.Detail(ErrNoHtmxAsset, "path %[1]q | 路径 %[1]q", manifestPath)
	}
	if !validVersionToken(htmx.Version) {
		return nil, errs.Detail(ErrNoHtmxAsset, "htmx version %[1]q is not a version token | htmx 版本 %[1]q 不是合法版本记号", htmx.Version)
	}
	ydxVersions, ydxModules := ydxInventory(allModules)
	var wafVersion, crsVersion string
	if HasScaffold(fsys, dir) {
		wafVersion, crsVersion, err = loadWAFVersions(fsys, dir)
		if err != nil {
			return nil, err
		}
	}
	return &Inventory{
		ModulePath:        modulePath,
		GoDirective:       goDirective,
		Modules:           modules,
		Assets:            m.Assets,
		HtmxVersion:       htmx.Version,
		YdxVersions:       ydxVersions,
		YdxModules:        ydxModules,
		WafModuleVersion:  wafVersion,
		CRSRulesetVersion: crsVersion,
	}, nil
}

// localReplaceVersion is the zero pseudo-version `yd new --local-replace` writes into a generated go.mod. |
// localReplaceVersion 是 `yd new --local-replace` 写入生成 go.mod 的零伪版本。
//
// It carries no meaning: the replace directive decides which code is used. Treating it as a real version
// makes a project that only imports part of ydx look like a version conflict after `go build -mod=mod`. |
// 它没有实际含义：使用哪份代码由 replace 指令决定。把它当成真实版本，会让只 import 部分 ydx 模块的项目
// 在 `go build -mod=mod` 之后看起来像版本冲突。
const localReplaceVersion = "v0.0.0-00010101000000-000000000000"

// ydxInventory derives the per-module ydx versions and paths from go.mod. Scaffold-only modules
// are kept in go.mod by the tools-tag imports in tools.go, so this is the single source for every
// pinned ydx version; no second hand-maintained table exists. | ydxInventory 从 go.mod 推导每个 ydx
// 模块的版本与路径。仅脚手架使用的模块由 tools.go 的 tools 标签导入保留在 go.mod 中，因此这里是
// 所有 ydx 锁定版本的唯一来源，不再维护第二份手工表。
func ydxInventory(modules []Module) (map[string]string, []string) {
	versions := make(map[string]string)
	paths := make(map[string]bool, len(modules))
	for _, m := range modules {
		if m.Path != "github.com/shibingli/ydx" && !strings.HasPrefix(m.Path, "github.com/shibingli/ydx/") {
			continue
		}
		isBenchmark := strings.Contains(m.Path, "/benchmarks/") || m.Path == "github.com/shibingli/ydx/benchmarks"
		if isBenchmark {
			continue
		}
		paths[m.Path] = true
		// A local-replace placeholder says nothing about the real version. | local-replace
		// 占位版本不代表真实版本。
		if m.Version == localReplaceVersion {
			continue
		}
		versions[m.Path] = m.Version
	}
	if len(paths) == 0 {
		return nil, nil
	}
	out := make([]string, 0, len(paths))
	for modulePath := range paths {
		out = append(out, modulePath)
	}
	sort.Strings(out)
	return versions, out
}

// parseGoMod extracts the module path, the go directive and the direct requirements. | parseGoMod 提取模块路径、go 指令与直接依赖。
//
// The parser is deliberately small: it understands module/go/single-line require/require blocks,
// ignores comments and drops entries carrying the // indirect marker. Full go.mod grammar
// (replace, exclude, retract, toolchain) carries nothing this inventory needs. | 解析器刻意保持
// 精简：识别 module/go/单行 require/require 块，忽略注释，并丢弃带 // indirect 标记的条目。
// 完整的 go.mod 语法（replace、exclude、retract、toolchain）不承载本清单需要的任何信息。
func parseGoMod(src string) (modulePath, goDirective string, modules, allModules []Module, err error) {
	inBlock := false
	for _, raw := range strings.Split(src, "\n") {
		line := strings.TrimSpace(raw)
		if line == "" || strings.HasPrefix(line, "//") {
			continue
		}
		if inBlock {
			if line == ")" {
				inBlock = false
				continue
			}
			if m, ok, indirect := parseRequire(line); ok {
				allModules = append(allModules, m)
				if !indirect {
					modules = append(modules, m)
				}
			}
			continue
		}
		switch {
		case strings.HasPrefix(line, "module "):
			modulePath = strings.TrimSpace(strings.TrimPrefix(line, "module "))
		case strings.HasPrefix(line, "go "):
			goDirective = strings.TrimSpace(strings.TrimPrefix(line, "go "))
		case line == "require (":
			inBlock = true
		case strings.HasPrefix(line, "require "):
			if m, ok, indirect := parseRequire(strings.TrimPrefix(line, "require ")); ok {
				allModules = append(allModules, m)
				if !indirect {
					modules = append(modules, m)
				}
			}
		}
	}
	if modulePath == "" || goDirective == "" || inBlock {
		return "", "", nil, nil, ErrGoModInvalid
	}
	sort.Slice(modules, func(i, j int) bool { return modules[i].Path < modules[j].Path })
	sort.Slice(allModules, func(i, j int) bool { return allModules[i].Path < allModules[j].Path })
	return modulePath, goDirective, modules, allModules, nil
}

// parseRequire parses one "<path> <version>" require entry and reports whether it is indirect. |
// parseRequire 解析一条 “<路径> <版本>” 依赖，并报告是否为间接依赖。
func parseRequire(line string) (Module, bool, bool) {
	indirect := false
	if idx := strings.Index(line, "//"); idx >= 0 {
		indirect = strings.Contains(line[idx:], "indirect")
		line = strings.TrimSpace(line[:idx])
	}
	fields := strings.Fields(line)
	if len(fields) < 2 {
		return Module{}, false, false
	}
	return Module{Path: fields[0], Version: fields[1]}, true, indirect
}

// Generate renders the scaffold's generated version file. | Generate 渲染脚手架的版本生成文件。
func Generate(inv *Inventory) []byte {
	var b strings.Builder
	b.WriteString(generatedMarker)
	b.WriteString("\npackage scaffold\n\n")
	b.WriteString("// GoVersion is the Go directive of the framework module. | GoVersion 是框架模块的 go 指令。\n")
	b.WriteString("//\n// Source: go.mod. | 来源：go.mod。\n")
	// Quote instead of interpolating raw text: a hostile lockfile/go.mod value could otherwise
	// close the string and inject Go code into the generated file. | 使用引号而不是原样拼接：
	// 恶意的锁文件/go.mod 取值否则可以闭合字符串并向生成文件注入 Go 代码。
	b.WriteString("const GoVersion = " + strconv.Quote(inv.GoDirective) + "\n\n")
	b.WriteString("// HtmxVersion is the version of the htmx asset in web/assets.lock.json. | HtmxVersion 是 web/assets.lock.json 中 htmx 资产的版本。\n")
	b.WriteString("//\n// Source: the asset manifest entry named \"htmx\". | 来源：资产清单中名为 \"htmx\" 的条目。\n")
	b.WriteString("const HtmxVersion = " + strconv.Quote(inv.HtmxVersion) + "\n")
	if inv.WafModuleVersion != "" {
		b.WriteString("\n// WafModuleVersion is the ydx WAF module version pinned by the nested WAF dependency module. | WafModuleVersion 是嵌套 WAF 依赖模块锁定的 ydx WAF 模块版本。\n")
		b.WriteString("//\n// Source: tooling/versions/waf/go.mod. | 来源：tooling/versions/waf/go.mod。\n")
		b.WriteString("const WafModuleVersion = " + strconv.Quote(inv.WafModuleVersion) + "\n")
	}
	if inv.CRSRulesetVersion != "" {
		b.WriteString("\n// CRSRulesetVersion is the OWASP CRS version pinned by the nested WAF dependency module. | CRSRulesetVersion 是嵌套 WAF 依赖模块锁定的 OWASP CRS 版本。\n")
		b.WriteString("//\n// Source: tooling/versions/waf/go.mod. | 来源：tooling/versions/waf/go.mod。\n")
		b.WriteString("const CRSRulesetVersion = " + strconv.Quote(inv.CRSRulesetVersion) + "\n")
	}
	if len(inv.YdxVersions) > 0 {
		b.WriteString("\n// YdxVersions maps each ydx module pinned for generated projects to its own tag version. | YdxVersions 把生成项目锁定的每个 ydx 模块映射到它自己的标签版本。\n")
		b.WriteString("//\n// Source: the ydx requirements in go.mod, including scaffold-only modules kept there by tools.go. | 来源：go.mod 中的 ydx 依赖；仅脚手架使用的模块由 tools.go 保留在其中。\n")
		b.WriteString("var YdxVersions = map[string]string{\n")
		paths := make([]string, 0, len(inv.YdxVersions))
		for modulePath := range inv.YdxVersions {
			paths = append(paths, modulePath)
		}
		sort.Strings(paths)
		for _, modulePath := range paths {
			b.WriteString("\t" + strconv.Quote(modulePath) + ": " + strconv.Quote(inv.YdxVersions[modulePath]) + ",\n")
		}
		b.WriteString("}\n")
	}
	if len(inv.YdxModules) > 0 {
		b.WriteString("\n// YdxModules lists the ydx modules a generated project may import. | YdxModules 列出生成项目可能导入的 ydx 模块。\n")
		b.WriteString("//\n// Source: the ydx requirements in go.mod; scaffold-only modules are kept there by the tools-tag imports in tools.go. | 来源：go.mod 中的 ydx 依赖；仅脚手架使用的模块由 tools.go 的 tools 标签导入保留在其中。\n")
		b.WriteString("var YdxModules = []string{\n")
		for _, modulePath := range inv.YdxModules {
			b.WriteString("\t" + strconv.Quote(modulePath) + ",\n")
		}
		b.WriteString("}\n")
	}
	// Run the canonical formatter so a gofmt hook cannot make Check report drift on a file Sync
	// just wrote. The builder only emits valid Go, so a formatting failure is unreachable; falling
	// back to the raw text keeps Generate infallible. | 走一遍标准格式化，使 gofmt 钩子不会让
	// Check 对 Sync 刚写出的文件误报漂移。builder 只产出合法 Go，格式化失败不可达；回退原文
	// 使 Generate 保持无错误返回。
	if formatted, err := format.Source([]byte(b.String())); err == nil {
		return formatted
	}
	return []byte(b.String())
}

// Sync regenerates GeneratedPath from the sources and returns the written path. | Sync 从真源重新生成 GeneratedPath 并返回写入路径。
func Sync(fsys afero.Fs, dir string) (string, error) {
	inv, err := Load(fsys, dir)
	if err != nil {
		return "", err
	}
	path := filepath.Join(dir, filepath.FromSlash(GeneratedPath))
	if err := fsys.MkdirAll(filepath.Dir(path), 0o755); err != nil {
		return "", errs.WrapDetail(err, ErrGoMod, "path %[1]q | 路径 %[1]q", path)
	}
	if err := afero.WriteFile(fsys, path, Generate(inv), 0o644); err != nil {
		return "", errs.WrapDetail(err, ErrGoMod, "path %[1]q | 路径 %[1]q", path)
	}
	return filepath.ToSlash(path), nil
}

// Check reports whether GeneratedPath still matches the sources. | Check 报告 GeneratedPath 是否仍与真源一致。
//
// A missing file and stale content both return ErrGeneratedDrift; the caller turns it into an
// actionable "run yd versions sync" message. | 文件缺失与内容过期都返回 ErrGeneratedDrift；
// 调用方据此给出可执行的「运行 yd versions sync」提示。
func Check(fsys afero.Fs, dir string) error {
	inv, err := Load(fsys, dir)
	if err != nil {
		return err
	}
	path := filepath.Join(dir, filepath.FromSlash(GeneratedPath))
	got, err := afero.ReadFile(fsys, path)
	if err != nil {
		if errors.Is(err, fs.ErrNotExist) {
			return errs.Detail(ErrGeneratedDrift, "missing %[1]q | 缺少 %[1]q", path)
		}
		return errs.WrapDetail(err, ErrGeneratedDrift, "path %[1]q | 路径 %[1]q", path)
	}
	if string(got) != string(Generate(inv)) {
		return errs.Detail(ErrGeneratedDrift, "path %[1]q | 路径 %[1]q", path)
	}
	return nil
}
